7	/**
8	 * The centerpiece animated "product screen" for the migration landing page.
9	 *
10	 * A single app-window mock (ScreenFrame) that loops through the real migration
11	 * flow so the marketing page feels alive and premium without overclaiming:
12	 *
13	 *   0. Connect your old server   — host + SSH, one "Scan" button
14	 *   1. Scanning…                 — read-only probes running on the source
15	 *   2. Here's what we found      — detected apps / containers / databases fill in
16	 *   3. One click → migrating     — progress bar with the real worker phase labels
17	 *   4. Migrated & running ✓       — green verified checks
18	 *
19	 * All copy mirrors what the wizard/worker actually do (auto-detect via read-only
20	 * SSH, no DB passwords, installs prerequisites, copies to the same paths, brings
21	 * Docker/compose + services up, verifies what's running).
22	 *
23	 * Motion is JS-driven (a small step machine, same pattern as AnimatedHero) but
24	 * honours prefers-reduced-motion: those users get the finished "running" state
25	 * rendered statically, with no loop and no intermediate motion.
26	 */
27	
28	type Step = 0 | 1 | 2 | 3 | 4;
29	
30	// Detected items — mirrors detectSource() output (signatures, size labels, DBs).
31	const FOUND = [
32	  { icon: <IconCode size={15} />, label: "WordPress site", path: "/var/www/html", size: "4.2 GB" },
33	  { icon: <IconApps size={15} />, label: "Next.js app", path: "/srv/billing", size: "42 MB" },
34	  { icon: <IconServer size={15} />, label: "3 Docker containers", path: "redis · postgres · app", size: "compose" },
35	  { icon: <IconDisk size={15} />, label: "MySQL + PostgreSQL", path: "all databases · no password", size: "1.6 GB" },
36	];
37	
38	// Progress phases — the real report() labels from worker/migrate-real.ts.
39	const PHASES = [
40	  { at: 16, label: "Installing prerequisites…", detail: "Docker Engine + compose, MySQL, PostgreSQL, nginx" },
41	  { at: 40, label: "Copying files…", detail: "to the same paths on your new server" },
42	  { at: 62, label: "Migrating databases…", detail: "dumped via root on the source — no password" },
43	  { at: 78, label: "Starting containers…", detail: "docker compose up -d" },
44	  { at: 94, label: "Verifying…", detail: "docker ps shows 3 running containers" },
45	];
46	
47	// Done state — the verified/running summary.
48	const RUNNING = [
49	  "Files restored to their original paths",
50	  "MySQL + PostgreSQL databases imported",
51	  "3 Docker containers up (compose)",
52	  "Ports 443, 3000, 6379 listening",
53	];
54	
55	function phaseFor(pct: number) {
56	  let p = PHASES[0];
57	  for (const ph of PHASES) if (pct >= ph.at) p = ph;
58	  return p;
59	}
