61	export function MigrationScreens() {
62	  const [step, setStep] = useState<Step>(0);
63	  const [revealed, setRevealed] = useState(0); // how many FOUND rows are in
64	  const [pct, setPct] = useState(0);
65	  const [reduced, setReduced] = useState(false);
66	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
67	
68	  useEffect(() => {
69	    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
70	    if (reduce) {
71	      // Rest on the finished, running state — no motion, no loop.
72	      setReduced(true);
73	      setStep(4);
74	      setRevealed(FOUND.length);
75	      setPct(100);
76	      return;
77	    }
78	
79	    let cancelled = false;
80	    const wait = (ms: number) =>
81	      new Promise<void>((res) => {
82	        const t = setTimeout(res, ms);
83	        timers.current.push(t);
84	      });
85	
86	    async function loop() {
87	      while (!cancelled) {
88	        // 0 — connect
89	        setStep(0);
90	        setRevealed(0);
91	        setPct(0);
92	        await wait(2000);
93	        if (cancelled) return;
94	
95	        // 1 — scanning
96	        setStep(1);
97	        await wait(2100);
98	        if (cancelled) return;
99	
100	        // 2 — found (rows fill in one by one)
101	        setStep(2);
102	        for (let i = 1; i <= FOUND.length; i++) {
103	          if (cancelled) return;
104	          setRevealed(i);
105	          await wait(480);
106	        }
107	        await wait(1400);
108	        if (cancelled) return;
109	
110	        // 3 — one click → migrating (progress fills)
111	        setStep(3);
112	        setPct(0);
113	        for (let p = 0; p <= 100; p += 2) {
114	          if (cancelled) return;
115	          setPct(p);
116	          await wait(52);
117	        }
118	        await wait(500);
119	        if (cancelled) return;
120	
121	        // 4 — migrated & running
122	        setStep(4);
123	        await wait(3400);
124	      }
125	    }
126	
127	    loop();
128	    return () => {
129	      cancelled = true;
130	      timers.current.forEach(clearTimeout);
131	      timers.current = [];
132	    };
133	  }, []);
134	
135	  const liveLabel =
136	    step === 0 ? "ready" : step === 1 ? "scanning" : step === 3 ? "migrating" : step === 4 ? "running" : "detected";
137	
138	  return (
139	    <ScreenFrame
140	      title="Nxeon · Migration"
141	      icon={<IconServer size={13} />}
142	      live
143	      liveLabel={liveLabel}
144	      className="mx-auto w-full max-w-lg"
145	    >
146	      {/* Fixed height so the looping steps don't shift the page layout. */}
147	      <div className="relative min-h-[420px] p-4 sm:p-5">
148	        {/* Step 0 — connect ------------------------------------------------ */}
149	        <Pane show={step === 0}>
150	          <p className="text-[12px] font-medium text-slate-300">Connect your old server</p>
151	          <p className="mt-1 text-[11px] text-slate-500">Read-only. We never store your credentials.</p>
152	          <div className="mt-4 space-y-3">
153	            <Field label="Source host" value="203.0.113.24" mono />
154	            <div className="grid grid-cols-2 gap-3">
155	              <Field label="SSH port" value="22" mono />
156	              <Field label="User" value="root" mono />
157	            </div>
158	          </div>
159	          <div className="mt-5 flex items-center justify-center gap-2 rounded-xl border border-brand-500/30 bg-gradient-to-r from-accent-blue/20 to-brand-500/20 py-2.5 text-[12px] font-semibold text-brand-100">
160	            Scan my server <IconArrow size={14} />
161	          </div>
162	          <p className="mt-3 text-center text-[11px] text-slate-600">No agent to install. Nothing changes on this server.</p>
163	        </Pane>
164	
165	        {/* Step 1 — scanning ---------------------------------------------- */}
166	        <Pane show={step === 1}>
167	          <div className="flex h-full min-h-[380px] flex-col items-center justify-center text-center">
168	            <span className="relative flex h-14 w-14 items-center justify-center">
169	              <span className="absolute inset-0 rounded-full border-2 border-brand-500/20" />
170	              <span className="absolute inset-0 rounded-full border-2 border-transparent border-t-brand-400 motion-safe:animate-spin" />
171	              <IconServer size={22} />
172	            </span>
173	            <p className="mt-5 text-[13px] font-semibold text-white">Scanning your server…</p>
174	            <div className="mt-4 w-full max-w-xs space-y-1.5 text-left font-mono text-[11px] text-slate-500">
175	              <ScanLine text="detecting apps in /var/www, /srv, /home…" delay={0} />
176	              <ScanLine text="docker ps · reading running containers" delay={260} />
177	              <ScanLine text="ss -lntp · mapping listening ports" delay={520} />
178	              <ScanLine text="probing MySQL / PostgreSQL data dirs" delay={780} />
179	            </div>
180	          </div>
181	        </Pane>
182	
183	        {/* Step 2 — found -------------------------------------------------- */}
184	        <Pane show={step === 2}>
185	          <div className="flex items-center justify-between">
186	            <p className="text-[12px] font-medium text-slate-300">Here&apos;s what we found</p>
187	            <span className="rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
188	              {revealed}/{FOUND.length} detected
189	            </span>
190	          </div>
191	          <ul className="mt-3 space-y-2">
192	            {FOUND.map((f, i) => {
193	              const on = i < revealed;
194	              return (
195	                <li
196	                  key={f.label}
197	                  className={`flex items-center gap-3 rounded-xl border px-3 py-2.5 transition-all duration-300 ${
198	                    on
199	                      ? "border-white/[0.08] bg-white/[0.03] opacity-100"
200	                      : "translate-y-1 border-white/[0.04] bg-white/[0.01] opacity-30"
201	                  }`}
202	                >
203	                  <span
204	                    className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-lg transition-colors ${
205	                      on ? "bg-emerald-500/15 text-emerald-300" : "bg-white/[0.04] text-slate-600"
206	                    }`}
207	                  >
208	                    {on ? <IconCheck size={15} /> : f.icon}
209	                  </span>
210	                  <span className="min-w-0 flex-1">
211	                    <span className="block truncate text-[12px] font-medium text-slate-200">{f.label}</span>
212	                    <span className="block truncate font-mono text-[10px] text-slate-500">{f.path}</span>
213	                  </span>
214	                  <span className="shrink-0 rounded-md bg-white/[0.05] px-1.5 py-0.5 font-mono text-[10px] text-slate-400">
215	                    {f.size}
216	                  </span>
217	                </li>
218	              );
219	            })}
220	          </ul>
221	          <div className="mt-4 flex items-center justify-center gap-2 rounded-xl border border-brand-500/30 bg-gradient-to-r from-accent-blue/25 to-brand-500/25 py-2.5 text-[12px] font-semibold text-white">
222	            Migrate everything <IconArrow size={14} />
223	          </div>
224	        </Pane>
225	
226	        {/* Step 3 — migrating --------------------------------------------- */}
227	        <Pane show={step === 3}>
228	          <div className="flex h-full min-h-[380px] flex-col justify-center">
229	            <p className="text-[12px] font-medium text-slate-300">Migrating to nxeon-sg-01</p>
230	            <p className="mt-1 font-mono text-[11px] text-brand-200">{phaseFor(pct).label}</p>
231	            <p className="mt-0.5 font-mono text-[10px] text-slate-500">{phaseFor(pct).detail}</p>
232	
233	            <div className="mt-4 h-2.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
234	              <div
235	                className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-[width] duration-100 ease-linear"
236	                style={{ width: `${pct}%` }}
237	              />
238	            </div>
239	            <p className="mt-1.5 text-right font-mono text-[10px] text-slate-500">{pct}%</p>
240	
241	            <ul className="mt-4 space-y-1.5">
242	              {PHASES.map((ph) => {
243	                const done = pct > ph.at + 4;
244	                const active = !done && pct >= ph.at - 8;
245	                return (
246	                  <li key={ph.label} className="flex items-center gap-2.5 text-[11px]">
247	                    <span
248	                      className={`flex h-4 w-4 shrink-0 items-center justify-center rounded-full ${
249	                        done
250	                          ? "bg-emerald-500/15 text-emerald-300"
251	                          : active
252	                            ? "bg-brand-500/20 text-brand-200"
253	                            : "border border-white/10 text-transparent"
