263	                      {ph.label}
264	                    </span>
265	                  </li>
266	                );
267	              })}
268	            </ul>
269	          </div>
270	        </Pane>
271	
272	        {/* Step 4 — running ------------------------------------------------ */}
273	        <Pane show={step === 4}>
274	          <div className="flex h-full min-h-[380px] flex-col justify-center">
275	            <div className="flex flex-col items-center text-center">
276	              <span className="flex h-14 w-14 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300 ring-1 ring-emerald-500/30">
