280	              <p className="mt-1 text-[11px] text-slate-500">on nxeon-sg-01 · verified live</p>
281	            </div>
282	            <ul className="mt-5 space-y-2">
283	              {RUNNING.map((r) => (
284	                <li key={r} className="flex items-center gap-2.5 rounded-lg bg-emerald-500/[0.06] px-3 py-2 text-[12px] text-slate-200">
