/** Cover for a card: real image if present, else the gradient/emoji block. */
function CardCover({
  coverImage,
  coverEmoji,
  className,
  emojiClassName,
}: {
  coverImage: string | null;
  coverEmoji: string | null;
  className: string;
  emojiClassName: string;
}) {
  if (coverImage) {
    return (
      <div className={`overflow-hidden ${className}`}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={coverImage}
          alt=""
          loading="lazy"
          className="h-full w-full object-cover"
        />
      </div>
    );
  }
  return (
    <div className={`${className} ${emojiClassName}`}>
      <span>{coverEmoji ?? "📝"}</span>
    </div>
  );

