// Throwaway screenshot capture for blog imagery.
// Captures polished public showcase UI from https://nxeon.cloud into
// public/blog/screenshots/*.png. CAPTURE-ONLY — no deploy/prisma/restart.
//
//   node scripts/capture-screens.mjs
//
import { chromium } from "playwright";
import { mkdirSync, statSync, existsSync, unlinkSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const OUT = join(ROOT, "public", "blog", "screenshots");
const BASE = process.env.BASE_URL || "https://nxeon.cloud";
mkdirSync(OUT, { recursive: true });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ScreenFrame showcase components — captured as element screenshots by the
// exact header title text (anchored to the .rounded-2xl app-window root).
const FRAMES = [
  { file: "server-dashboard.png",       url: "/",              title: "web-prod-01 · sgp1" },
  { file: "mail-inbox.png",             url: "/",              title: "you@yourbrand.com" },
  { file: "dns-manager.png",            url: "/",              title: "DNS · yourbrand.com" },
  { file: "migration-center.png",       url: "/",              title: "Nxeon · Migration" },
  { file: "game-servers.png",           url: "/game-servers",  title: "Minecraft · survival-smp" },
  { file: "block-storage-volumes.png",  url: "/block-storage", title: "Volumes" },
  { file: "ai-builder.png",             url: "/features",      title: "Claude · connected to web-prod-01" },
];

// Non-frame element captures via CSS selector.
const SELECTORS = [
  { file: "deploy-wizard.png",    url: "/",                       sel: ".glass.rounded-2xl" },
  { file: "pricing-plans.png",    url: "/pricing",                sel: "div.grid.xl\\:grid-cols-4" },
  { file: "blog-index.png",       url: "/blog",                   sel: "div.grid.lg\\:grid-cols-3" },
  { file: "domain-generator.png", url: "/tools/domain-generator", sel: "section.relative .card" },
  { file: "free-tools.png",       url: "/tools",                  sel: "div.grid.lg\\:grid-cols-3.mt-10" },
];

const results = [];

async function settle(page, url) {
  await page.goto(BASE + url, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
  await page.evaluate(() => window.scrollTo(0, 0));
  await sleep(700);
}

async function shoot(loc, file) {
  const path = join(OUT, file);
  await loc.scrollIntoViewIfNeeded({ timeout: 8000 });
  await sleep(1100); // Reveal opacity/transform + bar animations settle
  await loc.screenshot({ path });
  const kb = statSync(path).size / 1024;
  const ok = kb > 15;
  if (!ok && existsSync(path)) unlinkSync(path);
  results.push({ file, ok, kb: Math.round(kb) });
  console.log(`${ok ? "OK " : "BAD"}  ${file.padEnd(28)} ${Math.round(kb)}KB`);
  return ok;
}

const run = async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    deviceScaleFactor: 2,
    reducedMotion: "reduce", // rest looping mocks on a clean, deterministic frame
  });
  const page = await ctx.newPage();

  for (const t of FRAMES) {
    try {
      await settle(page, t.url);
      const loc = page
        .locator("div.rounded-2xl")
        .filter({ has: page.locator(".truncate", { hasText: t.title }) })
        .first();
      await loc.waitFor({ state: "visible", timeout: 15000 });
      await shoot(loc, t.file);
    } catch (e) {
      console.log(`ERR  ${t.file}: ${e.message.split("\n")[0]}`);
      results.push({ file: t.file, ok: false, kb: 0 });
    }
  }

  for (const t of SELECTORS) {
    try {
      await settle(page, t.url);
      const loc = page.locator(t.sel).first();
      await loc.waitFor({ state: "visible", timeout: 15000 });
      await shoot(loc, t.file);
    } catch (e) {
      console.log(`ERR  ${t.file}: ${e.message.split("\n")[0]}`);
      results.push({ file: t.file, ok: false, kb: 0 });
    }
  }

  await browser.close();
  const good = results.filter((r) => r.ok);
  console.log(`\n=== ${good.length}/${results.length} captured ===`);
  console.log(good.map((r) => "/blog/screenshots/" + r.file).join("\n"));
};

run().catch((e) => {
  console.error(e);
  process.exit(1);
});

